class Solution {
public:
    bool validPartition(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<bool> dp(n + 1, false);
        dp[0] = true;
        for (int i = 2; i <= n; ++i) {
            if (nums[i - 1] == nums[i - 2] && dp[i - 2]) dp[i] = true;
            if (i >= 3 && dp[i - 3]) {
                if (nums[i - 1] == nums[i - 2] && nums[i - 2] == nums[i - 3]) dp[i] = true;
                else if (nums[i - 1] == nums[i - 2] + 1 && nums[i - 2] == nums[i - 3] + 1) dp[i] = true;
            }
        }
        return dp[n];
    }
};

class Solution {
    public boolean validPartition(int[] nums) {
        int n = nums.length;
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 2; i <= n; ++i) {
            if (nums[i - 1] == nums[i - 2] && dp[i - 2]) dp[i] = true;
            if (i >= 3 && dp[i - 3]) {
                if (nums[i - 1] == nums[i - 2] && nums[i - 2] == nums[i - 3]) dp[i] = true;
                else if (nums[i - 1] == nums[i - 2] + 1 && nums[i - 2] == nums[i - 3] + 1) dp[i] = true;
            }
        }
        return dp[n];
    }
}

var validPartition = function(nums) {
    const n = nums.length;
    const dp = new Array(n + 1).fill(false);
    dp[0] = true;
    for (let i = 2; i <= n; ++i) {
        if (nums[i - 1] === nums[i - 2] && dp[i - 2]) dp[i] = true;
        if (i >= 3 && dp[i - 3]) {
            if (nums[i - 1] === nums[i - 2] && nums[i - 2] === nums[i - 3]) dp[i] = true;
            else if (nums[i - 1] === nums[i - 2] + 1 && nums[i - 2] === nums[i - 3] + 1) dp[i] = true;
        }
    }
    return dp[n];
};
